//! SSRF guard for website imports (port of the decision logic in `public_fetch.py`): which addresses count as public,
//! and which URLs may be fetched. The address tables are CPython's own (`src/ip_tables.json`, generated by
//! `parity/gen_ip_tables.py`) and change between Python releases, so regenerate them with production's interpreter.
use serde::Deserialize;
use std::net::IpAddr;
use std::sync::OnceLock;

#[derive(Deserialize)]
struct Tables {
    v4_private: Vec<String>,
    v4_exceptions: Vec<String>,
    v4_public: String,
    v6_private: Vec<String>,
    v6_exceptions: Vec<String>,
}

struct Parsed {
    v4_private: Vec<(u32, u8)>,
    v4_exceptions: Vec<(u32, u8)>,
    v4_public: (u32, u8),
    v6_private: Vec<(u128, u8)>,
    v6_exceptions: Vec<(u128, u8)>,
}

fn cidr4(s: &str) -> (u32, u8) {
    let (a, p) = s.split_once('/').expect("cidr");
    (
        u32::from(a.parse::<std::net::Ipv4Addr>().expect("v4")),
        p.parse().expect("prefix"),
    )
}
fn cidr6(s: &str) -> (u128, u8) {
    let (a, p) = s.split_once('/').expect("cidr");
    (
        u128::from(a.parse::<std::net::Ipv6Addr>().expect("v6")),
        p.parse().expect("prefix"),
    )
}

fn tables() -> &'static Parsed {
    static T: OnceLock<Parsed> = OnceLock::new();
    T.get_or_init(|| {
        let t: Tables =
            serde_json::from_str(include_str!("ip_tables.json")).expect("ip_tables.json");
        Parsed {
            v4_private: t.v4_private.iter().map(|s| cidr4(s)).collect(),
            v4_exceptions: t.v4_exceptions.iter().map(|s| cidr4(s)).collect(),
            v4_public: cidr4(&t.v4_public),
            v6_private: t.v6_private.iter().map(|s| cidr6(s)).collect(),
            v6_exceptions: t.v6_exceptions.iter().map(|s| cidr6(s)).collect(),
        }
    })
}

fn in4(ip: u32, (net, len): (u32, u8)) -> bool {
    len == 0 || (ip >> (32 - len as u32)) == (net >> (32 - len as u32))
}
fn in6(ip: u128, (net, len): (u128, u8)) -> bool {
    len == 0 || (ip >> (128 - len as u32)) == (net >> (128 - len as u32))
}

fn v4_global(ip: u32) -> bool {
    let t = tables();
    let private =
        t.v4_private.iter().any(|n| in4(ip, *n)) && !t.v4_exceptions.iter().any(|n| in4(ip, *n));
    !in4(ip, t.v4_public) && !private
}

/// `ipaddress.ip_address(text).is_global`; `None` when Python's parser would raise (or accept a form Rust cannot, such
/// as an IPv6 scope id), in which case the caller must treat the address as not public.
pub fn is_global(text: &str) -> Option<bool> {
    match text.parse::<IpAddr>().ok()? {
        IpAddr::V4(a) => Some(v4_global(u32::from(a))),
        IpAddr::V6(a) => {
            let ip = u128::from(a);
            if ip >> 32 == 0xFFFF {
                return Some(v4_global((ip & 0xFFFF_FFFF) as u32)); // IPv4-mapped: the IPv4 rules decide
            }
            let t = tables();
            let private = t.v6_private.iter().any(|n| in6(ip, *n))
                && !t.v6_exceptions.iter().any(|n| in6(ip, *n));
            Some(!private)
        }
    }
}

/// `public_addresses`: every resolved address must be public, and there must be at least one.
pub fn addresses_are_public(addresses: &[&str]) -> Result<(), &'static str> {
    if addresses.is_empty() || addresses.iter().any(|a| is_global(a) != Some(true)) {
        return Err("Website must resolve only to public internet addresses");
    }
    Ok(())
}

/// A `ValueError` raised by `urlsplit` or `.port`.
#[derive(Debug, PartialEq, Eq)]
pub struct ParseError;

#[derive(Debug, PartialEq, Eq)]
pub struct Split {
    pub scheme: String,
    pub username: Option<String>,
    pub password: Option<String>,
    pub hostname: Option<String>,
    /// `Err` when Python's `.port` raises `ValueError`.
    pub port: Result<Option<u32>, ParseError>,
}

/// The parts of `urllib.parse.urlsplit` the guard looks at. `Err` is a `ValueError` from `urlsplit` itself.
pub fn split(url: &str) -> Result<Split, ParseError> {
    let url: String = url
        .trim_start_matches(|c: char| c <= ' ')
        .chars()
        .filter(|c| !matches!(c, '\t' | '\r' | '\n'))
        .collect();
    let (scheme, rest) = match url.split_once(':') {
        Some((s, r))
            if !s.is_empty()
                && s.chars().next().unwrap().is_ascii_alphabetic()
                && s.chars()
                    .all(|c| c.is_ascii_alphanumeric() || "+-.".contains(c)) =>
        {
            (s.to_lowercase(), r.to_string())
        }
        _ => (String::new(), url.clone()),
    };
    let netloc = if let Some(after) = rest.strip_prefix("//") {
        let end = after.find(['/', '?', '#']).unwrap_or(after.len());
        after[..end].to_string()
    } else {
        String::new()
    };
    if (netloc.contains('[') && !netloc.contains(']'))
        || (netloc.contains(']') && !netloc.contains('['))
    {
        return Err(ParseError); // "Invalid IPv6 URL"
    }
    if let (Some((_, after_open)), true) = (netloc.split_once('['), netloc.contains(']')) {
        // Python 3.12+: a bracketed host must be IPv6 (or a well-formed IPvFuture); an IPv4 or a name in brackets raises.
        let host = after_open.split(']').next().unwrap_or("");
        let future = host.starts_with('v')
            && host[1..].split_once('.').is_some_and(|(h, rest)| {
                !h.is_empty() && h.chars().all(|c| c.is_ascii_hexdigit()) && !rest.is_empty()
            });
        if !(future || host.parse::<std::net::Ipv6Addr>().is_ok()) {
            return Err(ParseError);
        }
    }
    let (userinfo, hostinfo) = match netloc.rsplit_once('@') {
        Some((u, h)) => (Some(u.to_string()), h.to_string()),
        None => (None, netloc.clone()),
    };
    let (username, password) = match &userinfo {
        Some(u) => match u.split_once(':') {
            Some((a, b)) => (Some(a.to_string()), Some(b.to_string())),
            None => (Some(u.clone()), None),
        },
        None => (None, None),
    };
    let (hostname, port_text) = if let Some((_, bracketed)) = hostinfo.split_once('[') {
        let (h, after) = bracketed.split_once(']').unwrap_or((bracketed, ""));
        let port = after.split_once(':').map(|(_, p)| p.to_string());
        (h.to_string(), port)
    } else {
        match hostinfo.split_once(':') {
            Some((h, p)) => (h.to_string(), Some(p.to_string())),
            None => (hostinfo.clone(), None),
        }
    };
    let hostname = if hostname.is_empty() {
        None
    } else {
        Some(hostname.to_lowercase())
    };
    let port = match port_text.as_deref() {
        None | Some("") => Ok(None),
        Some(p) if p.chars().all(|c| c.is_ascii_digit()) => match p.parse::<u64>() {
            Ok(n) if n <= 65535 => Ok(Some(n as u32)),
            _ => Err(ParseError),
        },
        Some(_) => Err(ParseError),
    };
    Ok(Split {
        scheme,
        username,
        password,
        hostname,
        port,
    })
}

#[derive(Debug, PartialEq, Eq)]
pub enum UrlVerdict {
    Allowed,
    /// `ValueError('Website imports require same-site public HTTPS addresses')`.
    NotSameSitePublicHttps,
    /// Python raises a different `ValueError` while parsing.
    Unparseable,
}

/// The check at the top of `PublicClient.get`: HTTPS only, a host, no credentials, port 443, same site (ignoring `www.`).
pub fn url_verdict(url: &str, site_host: &str) -> UrlVerdict {
    let Ok(parts) = split(url) else {
        return UrlVerdict::Unparseable;
    };
    let Ok(port) = parts.port else {
        return UrlVerdict::Unparseable;
    };
    let site = site_host.to_lowercase();
    let site = site.strip_prefix("www.").unwrap_or(&site).to_string();
    let host = parts.hostname.clone().unwrap_or_default();
    let host = host.strip_prefix("www.").unwrap_or(&host).to_string();
    let creds = parts.username.as_deref().is_some_and(|u| !u.is_empty())
        || parts.password.as_deref().is_some_and(|p| !p.is_empty());
    if parts.scheme != "https"
        || parts.hostname.is_none()
        || creds
        || !matches!(port, None | Some(443))
        || host != site
    {
        return UrlVerdict::NotSameSitePublicHttps;
    }
    UrlVerdict::Allowed
}
